def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_moves = [h[0] for h in history]
    opp_moves = [h[1] for h in history]

    my_def = sum(1 for m in my_moves if m == 'D')
    opp_def = sum(1 for o in opp_moves if o == 'D')

    my_last = my_moves[-1]
    opp_last = opp_moves[-1]

    # If opponent defected first and we haven't, retaliate.
    if opp_def > 0 and my_def == 0:
        if opp_last == 'D':
            return 'D'
        else:
            return 'C'

    # Count how often opponent retaliated to our defections.
    ret_count = 0
    my_def_responses = 0
    for i in range(n - 1):
        if my_moves[i] == 'D':
            my_def_responses += 1
            if opp_moves[i + 1] == 'D':
                ret_count += 1

    ret_rate = ret_count / my_def_responses if my_def_responses > 0 else 0.0

    # If opponent has never defected, exploit cautiously.
    if opp_def == 0:
        if my_def > 0 and ret_count == 0:
            if my_def >= 3:
                return 'D'
            if n % 2 == 0:
                return 'D'
        if n >= 5 and rng.random() < 0.1:
            return 'D'
        return 'C'

    # If opponent retaliates frequently, cooperate mostly.
    if ret_rate > 0.5:
        if opp_last == 'D':
            if my_last == 'C':
                return 'D'
            else:
                return 'C'
        else:
            if n == 99:
                return 'D'
            return 'C'

    # Moderate tit-for-tat with forgiveness and occasional probing.
    if opp_last == 'D':
        if my_last == 'C':
            return 'D'
        else:
            if opp_def > n * 0.5:
                return 'D'
            else:
                return 'C'
    else:
        if my_last == 'D':
            return 'C'
        if opp_def < n * 0.2 and n < 95 and rng.random() < 0.15:
            return 'D'
        if n == 99:
            return 'D'
        return 'C'
